def fig(s, mod, key, bid, ratio, cap):
    en, ur, ps = mod.three(key)
    s.fig(bid, en, ur, ps, ratio, caption=cap)


def portrait(s, bid, en, ur, ps, cap):
    s.fig(bid, *[photo_figure(cap[0], [('', t)], c, w=260, cols=1, cell_h=150) for t, c in
                 ((en, 'Portrait in the book'), (ur, 'کتاب میں تصویر'), (ps, 'په کتاب کې انځور'))], .3, caption=cap)


